cssCode:
.compass-wrap {
  position: relative; width: 140px; height: 140px;
  border: 4px solid rgba(255, 255, 255, 0.2); border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 0 30px rgba(0, 255, 204, 0.2), inset 0 0 20px rgba(0, 255, 204, 0.1);
}
.compass-dial {
  position: absolute; width: 100%; height: 100%;
  border-radius: 50%; transition: transform 0.1s ease-out;
}
.needle {
  position: absolute; bottom: 50%; left: calc(50% - 3px);
  width: 6px; height: 45%; background: linear-gradient(to top, transparent, #00ffcc);
  border-radius: 3px; transform-origin: bottom center;
}
.center-dot {
  width: 16px; height: 16px; background: #fff; border-radius: 50%;
  box-shadow: 0 0 10px #fff; z-index: 10;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;touch-action:none;';

const wrap = document.createElement('div');
wrap.className = 'compass-wrap';

const dial = document.createElement('div');
dial.className = 'compass-dial';

const needle = document.createElement('div');
needle.className = 'needle';

const dot = document.createElement('div');
dot.className = 'center-dot';

dial.appendChild(needle);
wrap.appendChild(dial);
wrap.appendChild(dot);
c.appendChild(wrap);

c.addEventListener('pointermove', (e) => {
  const rect = wrap.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  // કર્સરની દિશા મુજબ એંગલ ગણવો
  const angle = Math.atan2(e.clientY - cy, e.clientX - cx) * (180 / Math.PI) + 90;
  dial.style.transform = `rotate(${angle}deg)`;
});
